from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class PlanActivationV2(SchemaObject):
    id = SchemaField(name="id", not_null=True)
    isCompleted = SchemaField(name="is_completed", not_null=True)
    links = SchemaField(name="links", not_null=True)

    def __init__(self, id, isCompleted, links):
        self.id = id
        self.isCompleted = isCompleted
        self.links = links

        super(PlanActivationV2, self).__init__()
